targets.query:
from(bucket: "walenstadt-wind")
  |> range(start: v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "max_wind_speed" and r._field == "value"
  )
  |> map(fn: (r) => ({r with _value: r._value * 3.6}))
  |> pivot(rowKey: ["_time"], columnKey: ["_measurement"], valueColumn: "_value")
  |> map(fn: (r) => ({
    r with 
    Böe: if r.max_wind_speed > 100 then r.avg_wind_speed else r.max_wind_speed,
  }))
  |> drop(columns: ["max_wind_speed", "min_wind_speed", "avg_wind_speed"])
  |> keep(columns: ["_time", "Böe"])

from(bucket: "walenstadt-wind")
  |> range(start: v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "min_wind_speed" and r._field == "value"
  )
  |> map(fn: (r) => ({r with _value: if r._value > 100 then 0.0 else r._value * 3.6 * 2.0}))

options.getOption:
// Find the series with level data
const levelSeries = context.panel.data.series.find(s =>
  s.fields.some(f => f.name === "level")
);

if (!levelSeries) {
  return {
    title: {
      text: "No level data available",
      textStyle: { fontSize: 20 }
    }
  };
}

const levelField = levelSeries.fields.find(f => f.name === "level");
if (!levelField || !levelField.values || levelField.values.length === 0) {
  return {
    title: {
      text: "No level values available",
      textStyle: { fontSize: 20 }
    }
  };
}

const currentLevel = levelField.values.at(-1);
const level_percentage = Math.abs((currentLevel - 418) / 3);

// Find temperature data
let currentTemperature = null;
for (const series of context.panel.data.series) {
  const tempField = series.fields.find(f => f.name === "temperature");
  if (tempField && tempField.values && tempField.values.length > 0) {
    currentTemperature = tempField.values.at(-1);
    break;
  }
}

// Dynamic color functions
function getLevelColor(level) {
  if (level >= 420) return '#FF4444';      // Red - Critical
  if (level >= 419.5) return '#FFA500';   // Orange - Warning
  return '#4CAF50';                       // Green - Normal
}

// Temperature color function (solid colors work better for text)
function getTemperatureColor(temp) {
  if (temp === null) return '#CCCCCC';     // Gray if no temperature
  if (temp >= 22) return '#FF4444';       // Red - Very warm
  if (temp >= 18) return '#FF8C00';       // Orange - Warm
  if (temp >= 15) return '#FFD700';       // Gold - Pleasant
  if (temp >= 10) return '#87CEEB';       // Sky blue - Cool
  if (temp >= 5) return '#4169E1';        // Royal blue - Cold
  return '#000080';                       // Navy - Very cold
}

return {
  series: [{
    type: 'liquidFill',
    data: [level_percentage],
    outline: {
      show: false
    },
    shape: "container",
    label: {
      formatter: function () {
        let labelText = `{level|${currentLevel} M.ü.M}`;
        if (currentTemperature !== null) {
          const tempFormatted = currentTemperature.toFixed(1);
          labelText += `{space|     }{temp|${tempFormatted} °C}`;  // Multiple spaces for spacing
        }
        return labelText;
      },
      fontSize: 30,
      rich: {
        level: {
          color: getLevelColor(currentLevel),
          fontWeight: 'bold',
          fontSize: 30,
          textShadowColor: '#000000',
          textShadowBlur: 2,
          textShadowOffsetX: 1,
          textShadowOffsetY: 1
        },
        temp: {
          color: getTemperatureColor(currentTemperature),
          fontWeight: 'bold',
          fontSize: 30,
          textShadowColor: '#000000',
          textShadowBlur: 2,
          textShadowOffsetX: 1,
          textShadowOffsetY: 1
        },
        space: {
          color: 'transparent',  // Invisible spacing
          fontSize: 30
        }
      }
    },
    amplitude: 5
  }]
};

