options.getOption:
// Transform InfluxDB data to ECharts wind format
const data = context.panel.data;
const series = data.series[0];

if (!series || !series.fields) {
  return { title: { text: 'No data available' } };
}

// Find time, speed, direction, and gust fields
const timeField = series.fields.find(f => f.name === '_time');
const speedField = series.fields.find(f => f.name === 'min');
const directionField = series.fields.find(f => f.name === 'wind_direction');
const gustField = series.fields.find(f => f.name === 'max');

if (!timeField || !speedField || !directionField) {
  return { title: { text: 'Missing required fields (speed, direction)' } };
}

// Create wind data array for ECharts
const wind = [];
const gusts = [];

for (let i = 0; i < timeField.values.length; i++) {
  const time = new Date(timeField.values[i]).toISOString();
  const speed = parseFloat((speedField.values[i] || 0).toFixed(1));
  const direction = directionField.values[i] || 0;
  const gust = gustField ? parseFloat((gustField ? (gustField.values[i] || 0) : 0).toFixed(1)) : 0;

  wind.push({
    value: [time, speed],
    symbolRotate: (360 - direction) % 360,
    originalSpeed: speed // Store original speed for tooltip
  });

  gusts.push({
    value: [time, gust]
  });
}

// Calculate dynamic arrowY position based on data
const maxGust = Math.max(...gusts.map(g => g.value[1]));
const maxSpeed = Math.max(...wind.map(w => w.originalSpeed));
const maxValue = Math.max(maxGust, maxSpeed);
const arrowY = maxValue + Math.round(maxValue * 0.1); // 10% above the highest value

return {
  xAxis: {
    type: 'time',
    axisLabel: {
      formatter: function (value) {
        return new Date(value).toLocaleTimeString('de-CH', {
          hour: '2-digit',
          minute: '2-digit',
          hour12: false
        });
      }
    }
  },
  yAxis: {
    type: 'value',
    name: '[km/h]',
    min: 0,
    max: arrowY,
    splitLine: {
      show: true,           // Hide all grid lines
      lineStyle: {
        color: '#ddd',       // Grid line color
        width: 0.3,            // Grid line width
        type: 'dashed',       // 'solid', 'dashed', 'dotted'
        opacity: 0.5         // Grid line opacity
      }
    }
  },
  series: [
    {
      name: 'Wind Line',
      data: wind.map(w => ({ value: [w.value[0], w.originalSpeed] })),
      type: 'line',
      symbol: 'circle',
      smooth: true,
      lineStyle: {
        width: 2,
        opacity: 0.5
      }
    },
    {
      name: 'Wind Arrows',
      data: wind.map(w => ({
        value: [w.value[0], arrowY],
        symbolRotate: w.symbolRotate,
        itemStyle: {
          color: isWestWind(w.symbolRotate) ? '#65B581' : '#FD665F' // Green for West, Red for others
        }
      })),
      type: 'scatter',
      symbol: 'path://M0 0L15 10L30 0L15 30L0 0Z',
      symbolSize: 8,
      itemStyle: {
        opacity: 1
      }
    },
    {
      name: 'Gusts',
      data: gusts,
      type: 'line',
      smooth: true,
      symbol: 'circle', // No arrow symbols for gusts
      lineStyle: {
        width: 1,
        opacity: 0.7,
        type: 'dotted' // Dotted line for gusts
      },
      itemStyle: {
        opacity: 0.8
      }
    }
  ],
  visualMap: {
    show: false,
    min: 0,
    max: 15,
    inRange: {
      color: ['#FD665F', '#FFCE34', '#65B581']
    }
  },
  tooltip: {
    trigger: 'axis',
    formatter: function (params) {
      let tooltip = '';

      params.forEach(param => {
        const data = param.data;
        const time = new Date(data.value[0]).toLocaleString('de-CH', {
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          hour12: false
        });

        if (param.seriesName === 'Wind Line') {
          const speed = data.value[1];
          tooltip += `Zeit: ${time}<br/>Geschwindigkeit: ${speed} km/h`;
        } else if (param.seriesName === 'Wind Arrows') {
          const direction = (360 - data.symbolRotate) % 360;
          const directionText = getWindDirection(direction);
          tooltip += `<br/>Richtung: ${directionText} (${direction}°)`;
        } else if (param.seriesName === 'Gusts') {
          const gust = data.value[1];
          tooltip += `<br/>Böe: ${gust} km/h`;
        }
      });

      return tooltip;
    }
  },
  legend: {
    show: false
  },
  grid: {
    left: '7%',
    right: '5%',
    top: '10%',
    bottom: '10%'
  }
};

// Helper function to convert degrees to cardinal directions
function getWindDirection(degrees) {
  const directions = ['N', 'NNO', 'NO', 'ONO', 'O', 'OSO', 'SO', 'SSO', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
  const index = Math.round(degrees / 22.5) % 16;
  return directions[index];
}

function isWestWind(symbolRotate) {
  const direction = (360 - symbolRotate) % 360;
  // West wind is between 247.5° and 292.5° (W, WNW, NW)
  return direction >= 247.5 && direction <= 292.5;
}

